package com.bank.memo.service;

import java.util.logging.Logger;

// Longest contiguous palindrome via a boolean range table.
public class MemoScanService {
    private static final Logger log = Logger.getLogger(MemoScanService.class.getName());

    public int longestSymmetricRun(String memo) {
        int n = memo.length();
        if (n == 0) return 0;
        boolean[][] dp = new boolean[n][n];         // dp[i][j] true if i..j is palindrome
        int bestLen = 1;                            // any single char qualifies
        for (int i = n - 1; i >= 0; i--) {
            dp[i][i] = true;                        // single char palindrome
            for (int j = i + 1; j < n; j++) {
                boolean endsMatch = memo.charAt(i) == memo.charAt(j);
                boolean innerOk = j - i < 2 || dp[i + 1][j - 1];
                if (endsMatch && innerOk) {
                    dp[i][j] = true;                // ends match and inner palindrome
                    if (j - i + 1 > bestLen) bestLen = j - i + 1;
                }
            }
        }
        final int r = bestLen;
        log.info(() -> "Longest symmetric run in memo = " + r);
        return bestLen;
    }
}
